abelledby="home-os-windows"><div class="home-command-heading"><span id="home-terminal-name">PowerShell</span><button type="button" id="home-copy-commands"><svg aria-hidden="true"><use href="#home-copy"/></svg><span data-home-i18n="copy">Copy commands</span></button></div><pre><code id="home-commands">git clone --branch integrate/all-govern-updates https://github.com/Esmeevanleeuwen/govern.git
cd govern
.\start.cmd</code></pre></div><p class="home-copy-status" id="home-copy-status" role="status" aria-live="polite"></p><p class="home-after-setup"><span data-home-i18n="openAfter">Then open</span> <a href="http://localhost:8080">localhost:8080</a> <span data-home-i18n="registerAfter">and sign in, or create the first owner account for a new installation.</span></p><a class="home-text-link" href="https://github.com/Esmeevanleeuwen/govern/tree/integrate/all-govern-updates#beginnen"><span data-home-i18n="fullSetup">Read the full setup guide</span><svg aria-hidden="true"><use href="#home-outward"/></svg></a></dialog>

